package com.hms.config;
import com.hms.notifications.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.*; import org.springframework.core.env.Environment; import org.springframework.web.client.RestClient;
@Configuration @ConditionalOnProperty(name="hms.notifications.provider",havingValue="webhook") public class NotificationProviderConfig { @Bean RestClient.Builder notificationRestClient(){return RestClient.builder();} @Bean NotificationProvider smsWebhook(RestClient.Builder b,Environment e){return new WebhookNotificationProvider(NotificationChannel.SMS,e.getProperty("hms.notifications.webhook.sms"),b);} @Bean NotificationProvider emailWebhook(RestClient.Builder b,Environment e){return new WebhookNotificationProvider(NotificationChannel.EMAIL,e.getProperty("hms.notifications.webhook.email"),b);} @Bean NotificationProvider whatsappWebhook(RestClient.Builder b,Environment e){return new WebhookNotificationProvider(NotificationChannel.WHATSAPP,e.getProperty("hms.notifications.webhook.whatsapp"),b);} }
